<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
$user=require_role('admin');
$counts=[
 'users'=>(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn(),
 'auctions'=>(int)db()->query('SELECT COUNT(*) FROM auctions')->fetchColumn(),
 'items'=>(int)db()->query('SELECT COUNT(*) FROM auction_items')->fetchColumn(),
 'bids'=>(int)db()->query('SELECT COUNT(*) FROM bids')->fetchColumn(),
 'audit'=>(int)db()->query('SELECT COUNT(*) FROM audit_events')->fetchColumn()
];
$recent=db()->query("SELECT a.id,a.title,a.status,a.created_at,COUNT(i.id) AS item_count FROM auctions a LEFT JOIN auction_items i ON i.auction_id=a.id GROUP BY a.id ORDER BY a.created_at DESC,a.id DESC LIMIT 5")->fetchAll();
?>
